import { Pipe, PipeTransform, QueryList, TemplateRef } from '@angular/core';
import { TransferListContext, TransferListItem, TransferListTemplateType } from '../interfaces/transfer-list.interface';
import { SprTransferListTemplateDirective } from '../directives/spr-transfer-list-template.directive';

@Pipe({
  name: 'getTemplate',
  standalone: true,
})
export class GetTemplatePipe implements PipeTransform {
  transform(
    templates: QueryList<SprTransferListTemplateDirective> | undefined,
    templateType: TransferListTemplateType,
  ): TemplateRef<TransferListContext<TransferListItem>> | undefined {
    return templates?.find((item) => item.sprTransferListTemplate === templateType)?.template;
  }
}
