import { Component, Input, OnInit } from '@angular/core';
import { Router, RouterModule } from '@angular/router';
import { NgFor } from '@angular/common';
import { SprSidebarItemComponent } from './components/sidebar-item/spr-sidebar-item.component';
import { SidebarNavItem } from './interfaces/sidebar.interface';

@Component({
  selector: 'spr-sidebar',
  templateUrl: './spr-sidebar.component.html',
  styleUrls: ['./spr-sidebar.component.scss'],
  imports: [NgFor, RouterModule, SprSidebarItemComponent],
})
export class SprSidebarComponent implements OnInit {
  @Input() title?: string;
  @Input() items?: SidebarNavItem[] = [];

  constructor(private readonly route: Router) {}

  ngOnInit(): void {
    this.checkIfSubNavItemIsOpened();
  }

  closeOtherSubMenus(currentItem: SidebarNavItem): void {
    this.items = this.items?.map((item) => {
      if (item !== currentItem && item.subNavs && item.subNavs.length) {
        return {
          ...item,
          activeSub: false,
        };
      }

      return item;
    });
  }

  private checkIfSubNavItemIsOpened(): void {
    this.items = this.items?.map((item) => {
      if (item.subNavs && item.subNavs.length) {
        return {
          ...item,
          activeSub: this.route.url.includes(item.routerLink),
        };
      }

      return item;
    });
  }
}
