import { Pipe, PipeTransform } from '@angular/core';
import { TransferListItem } from '../interfaces/transfer-list.interface';

@Pipe({
  name: 'filteredList',
  standalone: true,
})
export class FilteredListPipe implements PipeTransform {
  transform(items: TransferListItem[], searchPredicate: string): TransferListItem[] {
    return this.sortAlphabetically(
      items.filter((item: TransferListItem) => item.name.toLowerCase().includes((searchPredicate || '').trim().toLowerCase())),
    );
  }

  private sortAlphabetically(items: TransferListItem[]): TransferListItem[] {
    return [...items].sort((a, b) => a.name.localeCompare(b.name));
  }
}
