import { ChangeDetectionStrategy, Component, ContentChildren, EventEmitter, inject, Input, Output, QueryList } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { TransferListItem, TransferListOutput, TransferListOutputSingle } from './interfaces/transfer-list.interface';
import { FilteredListPipe } from './pipes/filtered-list.pipe';
import { SprInputComponent } from '../input/spr-input.component';
import { SprButtonComponent } from '../button/spr-button.component';
import { SprTransferListTemplateDirective } from './directives/spr-transfer-list-template.directive';
import { GetTemplatePipe } from './pipes/get-template.pipe';
import { SprInnerHeaderComponent } from '../inner-header/spr-inner-header.component';

@Component({
  selector: 'spr-transfer-list',
  templateUrl: './spr-transfer-list.component.html',
  styleUrls: ['./spr-transfer-list.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    SprInputComponent,
    SprButtonComponent,
    FilteredListPipe,
    GetTemplatePipe,
    SprInnerHeaderComponent,
  ],
  providers: [FilteredListPipe],
})
export class SprTransferListComponent {
  @Input() sourceList: TransferListItem[] = [];
  @Input() targetList: TransferListItem[] = [];
  @Input() visibleHeader: string = '';
  @Input() countriesHeader: string = '';
  @Input() sourceColumnHeader: string = '';
  @Input() targetColumnHeader: string = '';
  @Input() searchPlaceholder: string = '';
  @Input() disabledItems: string[] = [];
  @Input() enabledItems: string[] = [];
  @Input() disabled: boolean = false;

  @Output() movedSingle = new EventEmitter<TransferListOutputSingle>();
  @Output() movedAll = new EventEmitter<TransferListOutput>();

  @ContentChildren(SprTransferListTemplateDirective) customTemplates?: QueryList<SprTransferListTemplateDirective>;

  private readonly filteredListPipe: FilteredListPipe = inject(FilteredListPipe);

  searchControl = new FormControl('', { nonNullable: true });

  moveToTarget(item: TransferListItem): void {
    if (this.enabledItems.includes(item.value) || this.disabled) {
      return;
    }

    this.sourceList = this.sourceList.filter((source: TransferListItem) => source.value !== item.value);
    this.targetList = this.targetList.concat(item);
    this.movedSingle.emit({
      sourceList: this.sourceList,
      targetList: this.targetList,
      direction: 'target',
      item,
    });
  }

  moveToSource(item: TransferListItem): void {
    if (this.disabledItems.includes(item.value) || this.disabled) {
      return;
    }

    this.targetList = this.targetList.filter((target: TransferListItem) => target.value !== item.value);
    this.sourceList = this.sourceList.concat(item);
    this.movedSingle.emit({
      sourceList: this.sourceList,
      targetList: this.targetList,
      direction: 'source',
      item,
    });
  }

  moveAllToTarget(): void {
    if (this.disabled) {
      return;
    }

    const filteredList = this.getFilteredList(this.sourceList).filter((item) => !this.enabledItems.includes(item.value));
    this.targetList = [...this.targetList, ...filteredList];

    this.sourceList = this.sourceList.filter((source: TransferListItem) => {
      return !filteredList.some((item: TransferListItem) => source.value === item.value);
    });

    this.movedAll.emit({
      sourceList: this.sourceList,
      targetList: this.targetList,
      direction: 'target',
    });
  }

  moveAllToSource(): void {
    if (this.disabled) {
      return;
    }

    const filteredList = this.getFilteredList(this.targetList).filter((item) => !this.disabledItems.includes(item.value));
    this.sourceList = [...this.sourceList, ...filteredList];

    this.targetList = this.targetList.filter((target: TransferListItem) => {
      return !filteredList.some((item: TransferListItem) => target.value === item.value);
    });

    this.movedAll.emit({
      sourceList: this.sourceList,
      targetList: this.targetList,
      direction: 'target',
    });
  }

  trackByName(index: number, item: TransferListItem): string {
    return item.value;
  }

  private getFilteredList(list: TransferListItem[]): TransferListItem[] {
    return this.filteredListPipe.transform(list, this.searchControl.value);
  }
}
