import { NgbDate } from '@ng-bootstrap/ng-bootstrap';
import { getDate, getMonth, getYear, isValid } from 'date-fns';

export const dateParse = (value: NgbDate | null | string): NgbDate | null => {
  const date = new Date(value as string);

  if (isValid(date)) {
    return new NgbDate(getYear(date), getMonth(date) + 1, getDate(date));
  }

  return null;
};

export const fromNgbDate = ({ day, year, month }: NgbDate): string => {
  return `${year}-${month < 10 ? '0' + month : month}-${day < 10 ? '0' + day : day}`;
};
