import { ChangeDetectionStrategy, Component, Input } from '@angular/core';
import { NgClass, NgForOf, NgIf } from '@angular/common';
import { RouterLink, RouterLinkActive } from '@angular/router';
import { SidebarNavItem } from '../../interfaces/sidebar.interface';

@Component({
  selector: 'spr-sidebar-item',
  templateUrl: './spr-sidebar-item.component.html',
  styleUrls: ['./spr-sidebar-item.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [NgForOf, NgIf, RouterLinkActive, RouterLink, NgClass],
})
export class SprSidebarItemComponent {
  @Input({ required: true }) item!: SidebarNavItem;

  toggleSubMenu(sidebarNavItem: SidebarNavItem): void {
    if (!sidebarNavItem.subNavs) {
      return;
    }

    this.item.activeSub = !this.item.activeSub;
  }
}
