import { Directive, Input, TemplateRef } from '@angular/core';
import { TransferListContext, TransferListItem, TransferListTemplateType } from '../interfaces/transfer-list.interface';

@Directive({ selector: '[sprTransferListTemplate]', standalone: true })
export class SprTransferListTemplateDirective {
  @Input({ required: true }) sprTransferListTemplate!: TransferListTemplateType;

  constructor(public template: TemplateRef<TransferListContext<TransferListItem>>) {}

  static ngTemplateContextGuard(
    directive: SprTransferListTemplateDirective,
    context: unknown,
  ): context is TransferListContext<TransferListItem> {
    return true;
  }
}
